import React from 'react'
type S={heading:string;text:string[]};type G={title:string;sections:S[]}
const guides:Record<string,G>={
"hra-calculator":{title:"HRA Calculator",sections:[
{heading:"How HRA exemption is calculated",text:["For Indian salaried employees, HRA exemption is generally the least of three amounts: actual HRA received, rent paid minus 10% of salary for HRA purposes, and 50% of qualifying salary for a metro residence or 40% for a non-metro residence.","The taxable HRA is the allowance received minus the eligible exemption."]},
{heading:"Use the correct salary base",text:["The salary used for HRA is not automatically gross salary or CTC.","It normally centers on basic salary and can include dearness allowance when it forms part of retirement benefits, plus qualifying commission expressed as a fixed percentage of turnover. Using take-home pay or total compensation can materially overstate the exemption."]},
{heading:"Metro versus non-metro treatment",text:["The 50% salary limit applies only to the specified metro cities recognized for HRA purposes; other locations use 40%.","A high-rent city is not automatically a metro for this rule. The residence location, rather than the employer office location, is what matters when selecting the applicable percentage."]},
{heading:"Rent actually paid matters",text:["HRA relief is linked to genuine rent paid for residential accommodation.","If rent is low, the rent-minus-10%-of-salary limb can become the limiting amount even when the employer pays a large HRA. If no rent is paid, merely receiving an HRA component does not create an exemption."]},
{heading:"Split the year when facts change",text:["A job change, salary revision, move between cities, change in rent, or switch between rented and owned accommodation can change the exemption during the year.","A more accurate calculation divides the year into periods with consistent facts and calculates each period separately before adding the results."]},
{heading:"Documents and rent evidence",text:["Keep the rent agreement, rent receipts and payment evidence consistent with the amounts claimed.","Employer payroll processes may request the landlord PAN above applicable rent thresholds. Documentation requirements and tax rules can change, so the calculator result should be checked against the relevant assessment year and employer process."]},
{heading:"HRA and the tax regime",text:["HRA exemption is associated with the old tax regime; the new regime generally does not provide the same HRA exemption.","Comparing regimes therefore requires more than comparing slab rates: deductions and exemptions forgone under the new regime can change which option produces the lower total tax."]},
{heading:"Worked interpretation",text:["Suppose qualifying salary is \u20b950,000 per month, HRA received is \u20b920,000, and rent is \u20b918,000.","Rent minus 10% of salary is \u20b913,000. The salary-percentage ceiling is \u20b925,000 in a metro or \u20b920,000 elsewhere, so the least amount is \u20b913,000 and the remaining \u20b97,000 HRA is taxable for that month."]},
{heading:"Common HRA mistakes",text:["Common errors include using annual figures for one input and monthly figures for another, treating CTC as qualifying salary, assuming every large city receives the 50% limit, ignoring mid-year changes, and claiming the full HRA received as exempt.","The least-of-three rule must be applied to compatible periods and definitions."]},
{heading:"What the result does not prove",text:["The calculator estimates exemption from the entered facts; it does not establish that a tenancy is genuine, that documentation is sufficient, or that a particular tax regime is optimal.","Tax treatment depends on current law and individual facts, so unusual arrangements deserve verification before filing a return."]},
]},
"roth-ira-calculator":{title:"Roth IRA Calculator",sections:[
{heading:"What a Roth IRA projection measures",text:["A Roth IRA projection estimates how contributions may compound inside an account funded with after-tax dollars.","Qualified withdrawals can be federal-income-tax-free when applicable requirements are satisfied. The future balance is therefore different from a taxable-account projection even when both portfolios earn the same pre-tax investment return."]},
{heading:"Contribution limits and eligibility",text:["Annual Roth IRA contribution limits and income phase-outs are set by tax year and can change.","Eligibility also depends on compensation and filing status. A calculator should not treat an entered contribution as automatically permitted; compare the assumption with current IRS limits and the rules that apply to the contributor."]},
{heading:"Contribution timing changes compounding",text:["A contribution made at the beginning of a year compounds longer than the same contribution made at year-end.","Monthly investing creates still another path. Over decades, timing differences accumulate, so projections should state whether contributions are modeled monthly, annually, at period start, or at period end."]},
{heading:"Return assumptions are not guarantees",text:["Expected return is a modeling assumption, not an IRA feature.","Stocks, bonds and other investments inside a Roth IRA can rise or fall. Testing several reasonable return assumptions is useful because a one-percentage-point difference compounded over 20 or 30 years can materially alter the projected balance."]},
{heading:"Inflation and purchasing power",text:["A future account value can look large while buying much less than the same number of dollars buys today.","For long retirement horizons, compare nominal future value with an inflation-adjusted value. Real purchasing power is often more useful for judging whether the projected Roth balance can support future spending."]},
{heading:"Contributions versus earnings",text:["Roth IRA contribution basis and investment earnings are not treated identically for distribution purposes.","Contributions can generally be withdrawn under more flexible rules, while earnings can be subject to qualification rules, taxes or penalties. A simple growth calculator should not imply that every dollar of the projected balance is immediately accessible without consequence."]},
{heading:"Five-year rules require care",text:["Roth IRAs have five-year concepts that can matter for qualified distributions and conversions.","These rules are more nuanced than a single account-age toggle, particularly when conversions are involved. Use the projection for accumulation planning, then verify distribution timing separately before relying on funds for a near-term need."]},
{heading:"Fees reduce the ending balance",text:["Fund expense ratios, advisory charges and other investment costs reduce the return that actually compounds.","A projection using a 7% gross return while paying meaningful annual costs will overstate the likely ending value. Where possible, use an expected return after recurring portfolio costs."]},
{heading:"Roth versus Traditional is a tax-rate question",text:["Choosing Roth rather than Traditional retirement saving often depends on the tax paid today versus the tax that would otherwise be paid when money is withdrawn.","The Roth balance alone cannot answer that question. Compare after-tax outcomes using current marginal rates, expected retirement rates, employer plan rules and available deductions."]},
{heading:"Use the calculator as a range",text:["A useful plan has a central projection plus lower-return and higher-return illustrations, while keeping contributions realistic.","Revisit the calculation after contribution-limit changes, income changes, asset-allocation changes or large market moves. The output is a planning estimate, not a promised retirement value."]},
]},
"uk-help-to-buy-vs-lisa-calculator":{title:"UK Help to Buy vs LISA Calculator",sections:[
{heading:"Understand the two schemes",text:["A Lifetime ISA and the legacy Help to Buy ISA use different contribution, bonus and property-purchase rules.","Help to Buy ISAs are closed to new accounts, although eligible existing holders may still use them. A comparison must therefore begin with the saver\u2019s actual account status rather than assuming both products are newly available."]},
{heading:"Government bonus mechanics",text:["The LISA generally adds a 25% government bonus to eligible contributions within its annual rules.","Help to Buy ISA bonuses are claimed through the conveyancing process and have their own limits. Comparing only headline bonus percentages misses differences in contribution ceilings, timing and how quickly the bonus becomes available."]},
{heading:"Property price caps matter",text:["First-home bonus eligibility is subject to scheme-specific property-price limits.","A purchase above the applicable ceiling can remove the expected benefit even if years of saving have already occurred. Test the intended purchase price rather than treating the government bonus as unconditional."]},
{heading:"LISA holding-period rule",text:["A LISA normally must have been open for at least 12 months before funds can be withdrawn without the unauthorized-withdrawal charge for an eligible first-home purchase.","Someone planning to buy sooner may face a timing problem that a simple balance comparison does not reveal."]},
{heading:"Withdrawal penalties can reverse the bonus",text:["Non-qualifying LISA withdrawals generally face a withdrawal charge.","Because the charge applies to the withdrawal amount after the government bonus has been added, it can remove the bonus and some of the saver\u2019s own money. Emergency-access needs therefore matter when deciding how much to lock into the account."]},
{heading:"Cash versus investment risk",text:["A LISA can hold cash or investments depending on the provider and product.","A first-home deposit needed soon may not tolerate stock-market volatility, while a longer horizon may support more investment risk. Compare the account wrapper separately from the investment held inside it."]},
{heading:"Contribution capacity and timeline",text:["Model contributions month by month or tax year by tax year, respecting current scheme limits.","A saver who can contribute more to a LISA may accumulate a larger bonus, but affordability and the planned purchase date determine whether that theoretical capacity is actually useful."]},
{heading:"Conveyancing and purchase eligibility",text:["The first-home withdrawal process has operational rules involving the conveyancer and eligible residential purchase.","Do not assume the calculator balance can simply be withdrawn to the buyer\u2019s current account without conditions. Confirm the current process before exchange and completion."]},
{heading:"Worked comparison logic",text:["Compare personal contributions, government bonuses, interest or investment growth, fees and any expected withdrawal charge over the same horizon.","Then test whether the target property satisfies each scheme\u2019s rules. A higher projected balance is irrelevant if the intended transaction cannot use the bonus."]},
{heading:"Rules can change",text:["ISA allowances, withdrawal charges and scheme guidance are policy-dependent.","Treat current thresholds as dated inputs and verify them with official UK guidance before acting. The calculator is most useful for illustrating mechanics and trade-offs, not guaranteeing future eligibility."]},
]},
"uk-premium-bonds-vs-cash-isa-calculator":{title:"UK Premium Bonds vs Cash ISA Calculator",sections:[
{heading:"Prize draw versus interest",text:["Premium Bonds do not pay a contractual interest rate to each holder.","Eligible bonds enter monthly prize draws, so an individual return can be zero, below the published prize-fund rate, or much higher. A Cash ISA normally pays stated interest, making its short-term outcome more predictable."]},
{heading:"Expected return is not guaranteed return",text:["Using the Premium Bonds prize-fund rate as if it were guaranteed interest can mislead.","The rate describes the overall prize pool, while prize distribution is uneven. Larger holdings generally make realized returns less erratic, but they still do not turn prizes into fixed interest."]},
{heading:"Tax treatment",text:["Premium Bond prizes are tax-free.","Cash ISA interest is also sheltered from UK income tax while it remains within the ISA wrapper. For many savers the comparison therefore turns more on expected return, certainty, access and ISA allowance usage than on a simple tax-rate adjustment."]},
{heading:"Personal Savings Allowance context",text:["Interest on ordinary savings outside an ISA may already fall within a saver\u2019s Personal Savings Allowance, depending on tax status and current rules.","That can affect the opportunity cost of using scarce ISA allowance for cash rather than investments. Compare the full household savings position, not only two account labels."]},
{heading:"Liquidity and access",text:["Premium Bonds can be cashed in, but withdrawal is not the same as instant bank-account access.","Cash ISA access depends on whether the product is easy-access, notice or fixed-term. Emergency funds should be judged on practical access time as well as nominal return."]},
{heading:"Inflation risk",text:["Both products can lose purchasing power when their effective return is below inflation.","Tax-free status does not prevent a real loss. For long horizons, calculate an inflation-adjusted value to see whether capital is expected to preserve purchasing power."]},
{heading:"ISA allowance has option value",text:["Money placed in a Cash ISA uses part of the annual ISA allowance under current rules.","Depending on circumstances, a saver may prefer to reserve ISA capacity for investments with larger expected taxable returns. This is a wrapper-allocation question that a simple rate comparison may omit."]},
{heading:"Model Premium Bonds as a distribution",text:["For a more realistic comparison, treat Premium Bond outcomes as uncertain rather than entering one guaranteed rate.","A central expected case plus lower-prize and higher-prize cases better reflects the product. The Cash ISA side can usually be modeled with the quoted rate for its guaranteed period."]},
{heading:"Safety and provider protection differ",text:["Premium Bonds are backed through NS&I arrangements, while bank or building-society deposits rely on the applicable deposit-protection framework and limits.","Large cash balances should consider institutional protection as well as yield."]},
{heading:"Choosing between them",text:["Premium Bonds may appeal to savers who value capital security, tax-free prizes and the draw structure; Cash ISAs may appeal to those prioritizing a known interest rate and tax shelter.","Compare expected pounds earned, certainty, access, allowance usage and the time horizon together."]},
]},
"mutual-fund-calculator":{title:"Mutual Fund Calculator",sections:[
{heading:"Lump-sum and SIP future value",text:["A lump-sum contribution compounds from one starting date, while an SIP creates a series of purchases with different holding periods. A fair projection therefore values each SIP instalment separately rather than pretending the full contribution was invested on day one. When comparing the two, keep the total amount contributed visible beside the ending value."]},
{heading:"NAV and units",text:["NAV is the per-unit value of a mutual fund after assets and liabilities are reflected. An investment amount divided by the applicable NAV determines units purchased, subject to the scheme’s transaction rules. NAV itself does not tell you whether a fund is cheap or expensive: a ₹20 NAV fund is not inherently better value than a ₹200 NAV fund."]},
{heading:"Return assumptions",text:["A constant annual return is a simplification used to make future-value math understandable. Real mutual-fund returns arrive unevenly, with positive and negative periods, so the same average return can produce different investor outcomes when contributions or withdrawals occur along the way. Use the assumed rate as a planning input, not a promised CAGR."]},
{heading:"Expense ratios",text:["Expense ratios are deducted inside the scheme and reduce the return that reaches investors. A small annual difference compounds over long horizons, especially for index-like strategies where gross performance may be similar. Compare direct and regular plans, and use net-of-fee return assumptions when the calculator allows it."]},
{heading:"Loads and transaction costs",text:["Some schemes or platforms can impose transaction charges, loads, or exit loads. These costs matter most when money is invested for short periods or redeemed inside the load window. A future-value projection that ignores an applicable exit load can overstate the amount actually available on redemption."]},
{heading:"Tax on distributions and gains",text:["Mutual-fund taxation depends on the type of fund, holding period, distribution treatment, and current tax law. Tax is generally triggered by taxable distributions or realization of gains rather than by the NAV merely rising. For planning, separate pre-tax portfolio growth from the cash an investor could keep after tax."]},
{heading:"Asset allocation and volatility",text:["Asset allocation determines much of a fund’s risk. An equity-heavy portfolio can have larger drawdowns than a high-quality bond allocation, while sector or thematic funds add concentration risk. The calculator’s return assumption should be plausible for the actual portfolio rather than borrowed from an unrelated asset class."]},
{heading:"Sequence risk",text:["Sequence risk matters when cash is entering or leaving the portfolio. For an SIP, falling prices early can buy more units; near a withdrawal date, the same decline can be harmful because units may need to be sold at depressed prices. Average-return projections hide this path dependency."]},
{heading:"Inflation-adjusted value",text:["Inflation converts nominal future value into purchasing-power terms. If a portfolio grows 8% while inflation averages 5%, the real increase is much smaller than the nominal balance suggests. Long goals such as retirement or education should be evaluated in today’s-money terms as well as future rupees."]},
{heading:"Benchmarking and rebalancing",text:["A useful benchmark matches the fund’s asset class and style; comparing a debt fund with an equity index says little about manager skill. Rebalancing is a separate portfolio decision that restores target weights after markets move. Judge performance after fees and over an appropriate period rather than reacting to a single strong or weak year."]}
]},
"sip-vs-mutual-fund-direct-plan-calculator":{title:"SIP vs Mutual Fund Direct Plan Calculator",sections:[
{heading:"SIP is a contribution method, direct plan is a fee class",text:["SIP and direct plan describe different things. SIP is a schedule for investing periodically, whereas a direct plan is a share class purchased without distributor commission embedded in the expense ratio. An investor can run an SIP into either a direct or regular plan, so the comparison should not present them as mutually exclusive products."]},
{heading:"Regular versus direct expense ratios",text:["Direct and regular variants of the same scheme normally hold the same underlying portfolio but charge different expense ratios. The regular plan includes distribution-related costs, which can create a persistent NAV and return gap over time. Compare the same scheme and option so that the fee difference is not confused with portfolio-selection differences."]},
{heading:"Monthly contribution timing",text:["Each monthly SIP instalment has its own purchase date and compounding period. A ₹10,000 contribution made this month has more time to grow than one made near the end of the projection. Accurate SIP math uses a recurring-cash-flow formula or iterates through instalments instead of multiplying one lump-sum result."]},
{heading:"Rupee-cost averaging",text:["Rupee-cost averaging means a fixed contribution buys more units when NAV is lower and fewer when NAV is higher. It can reduce the pressure to time entry points, but it does not guarantee profit or eliminate market risk. A steadily falling market can still leave the portfolio below total contributions for a period."]},
{heading:"Growth versus IDCW options",text:["Growth and IDCW options distribute economic return differently. In a growth option, gains remain reflected in NAV; an IDCW payout sends cash to the investor and the NAV adjusts accordingly. Treating a distribution as extra return would double count value, so comparisons should include both NAV change and cash received."]},
{heading:"Tracking the same scheme",text:["When testing direct versus regular, use the same fund, portfolio option, contribution dates, and return environment. Comparing unrelated schemes can make a performance gap look like a fee effect even though security selection or asset allocation caused it. The cleanest model isolates expense-ratio drag."]},
{heading:"Tax treatment",text:["Tax rules apply to the underlying mutual-fund category and transactions, not simply to whether the plan is direct or regular. Redemptions of SIP units can have different holding periods because each instalment is a separate lot. A withdrawal may therefore contain units with different tax treatment."]},
{heading:"Exit loads",text:["Exit-load clocks can also apply lot by lot to SIP purchases. Redeeming a large amount today may include older units outside the load period and newer units still subject to it. Short-horizon comparisons should model this rather than applying one load assumption to the entire account."]},
{heading:"Market volatility",text:["SIP discipline changes the timing of purchases, but it does not remove the volatility of the fund itself. Equity-fund SIPs can experience deep interim losses, while debt funds carry interest-rate and credit risks of their own. Choose the scheme based on the goal and horizon before optimizing plan costs."]},
{heading:"Fair comparison setup",text:["For a fair result, hold contribution amount, dates, scheme, option and gross portfolio return constant, then change only the regular-versus-direct cost. That isolates the compounding effect of the expense-ratio difference and shows why even modest annual fee gaps can become meaningful over long periods."]}
]},
"roth-ira-vs-traditional-ira-calculator":{title:"Roth IRA vs Traditional IRA Calculator",sections:[
{heading:"After-tax versus pre-tax contributions",text:["Roth IRA contributions are made with after-tax dollars, while a deductible Traditional IRA contribution can reduce current taxable income. Comparing equal account contributions can therefore require different take-home cash. A stronger model compares equal out-of-pocket cost as well as equal deposited amounts."]},
{heading:"Current marginal tax rate",text:["The current marginal tax rate determines the immediate value of a deductible Traditional contribution. A $6,000 deduction at a 24% marginal rate can save more current federal tax than the same deduction at 12%. State taxes and deduction eligibility can change the result further."]},
{heading:"Retirement withdrawal tax rate",text:["Traditional IRA withdrawals are generally taxable as ordinary income to the extent they represent pre-tax money, while qualified Roth IRA withdrawals can be tax-free. The future marginal rate is therefore central to the comparison: lower retirement tax rates tend to favor deferral, while higher rates strengthen the Roth case."]},
{heading:"Deductibility limits",text:["A Traditional IRA contribution is not automatically deductible. Workplace-plan coverage, income, filing status and tax-year thresholds can limit the deduction. If the contribution is nondeductible, basis must be tracked because future distributions can contain both taxable and nontaxable amounts."]},
{heading:"Roth income eligibility",text:["Direct Roth IRA contribution eligibility phases out at higher incomes under tax-year-specific rules. Exceeding the income range does not mean every Roth strategy is unavailable, but alternatives such as backdoor Roth contributions introduce pro-rata and reporting considerations that a simple calculator may not model."]},
{heading:"Required minimum distributions",text:["Traditional IRAs are generally subject to required minimum distribution rules at the applicable starting age, while original Roth IRA owners have different lifetime RMD treatment. Forced taxable distributions can affect later tax brackets, Medicare premiums and estate planning, so ending balance alone is not the whole decision."]},
{heading:"Conversion considerations",text:["A Roth conversion moves pre-tax IRA money into Roth status and usually creates taxable income in the conversion year. Conversions can be useful in temporarily low-tax years, but they can also push income into higher brackets or affect income-based thresholds. Conversion tax should ideally be paid from outside funds when feasible."]},
{heading:"Equal out-of-pocket comparison",text:["Equal-contribution comparisons can accidentally favor Traditional accounts because the current tax deduction leaves extra cash unmodeled. If that tax saving is spent, the behavior differs from a scenario where it is invested in a taxable account. Model both to understand the role of investor discipline."]},
{heading:"Investment growth and fees",text:["Both account types can hold similar investments, so market return and fund fees should normally be kept identical when isolating tax treatment. A higher assumed return magnifies the dollar value of tax-free Roth growth but also magnifies the value of tax deferral in a Traditional IRA."]},
{heading:"Estate and flexibility considerations",text:["Roth accounts offer flexibility through contribution-basis access and different estate characteristics, while Traditional accounts can be attractive for current deductions. Beneficiary rules, early-withdrawal rules, state taxation and charitable strategies can matter. The calculator should frame a tax tradeoff, not declare one IRA universally superior."]}
]},
"index-fund-vs-etf-calculator":{title:"Index Fund vs ETF Calculator",sections:[
{heading:"Fund structure versus investment strategy",text:["An index fund describes an investment strategy that tracks a benchmark; an ETF describes a trading structure. Many ETFs are index funds, and many traditional mutual funds also track indexes. Start by comparing two vehicles that follow the same or similar benchmark before attributing differences to structure."]},
{heading:"Expense ratios",text:["Expense ratios reduce investor returns inside both ETFs and mutual funds. When two products track the same index, a persistent fee gap can compound over decades. Very small fee differences may be less important than tracking quality, spreads, taxes or platform restrictions."]},
{heading:"Bid-ask spreads",text:["ETFs trade on an exchange and therefore have bid and ask prices. The spread is an implicit trading cost that is most noticeable in thinly traded funds or volatile markets. A commission-free trade can still have a cost if the investor buys at the ask and sells at the bid."]},
{heading:"Premiums and discounts to NAV",text:["An ETF’s market price can differ slightly from its net asset value, creating a premium or discount. Creation/redemption mechanisms usually keep large liquid ETFs close to NAV, but gaps can widen during market stress or in less liquid underlying assets."]},
{heading:"Intraday versus end-of-day trading",text:["Traditional mutual funds generally transact once per day at the calculated closing NAV, whereas ETFs can be traded throughout the session. Intraday flexibility can help with execution control, but it can also encourage unnecessary trading. Long-term investors may value automation more than minute-by-minute pricing."]},
{heading:"Fractional shares and automation",text:["Broker capabilities differ for automatic investing and fractional shares. Mutual funds often support exact-dollar recurring purchases, while ETF automation depends on the platform. If the investor contributes small fixed amounts, inability to buy fractional ETF shares can leave temporary cash drag."]},
{heading:"Tax efficiency",text:["ETF structure can be tax-efficient in taxable accounts because in-kind redemptions may reduce capital-gain distributions, though this is not guaranteed. Index mutual funds can also be highly tax-efficient. Inside retirement accounts, this structural tax difference is usually less important."]},
{heading:"Tracking difference",text:["Tracking difference is the gap between a fund’s actual return and its benchmark after fees and implementation effects. A fund with a slightly higher stated expense ratio can still track well if securities lending or portfolio management offsets part of the cost."]},
{heading:"Commissions and platform costs",text:["Platform commissions, account fees, currency conversion and minimum investment rules can outweigh tiny expense-ratio differences. Compare the investor’s actual brokerage setup rather than assuming every ETF trade is free or every mutual fund has no transaction fee."]},
{heading:"Choosing the underlying index",text:["The benchmark itself matters more than the wrapper. A total-market index, S&P 500 index and sector index have different diversification and risk even if all are available as ETFs and mutual funds. Choose exposure first; then optimize structure, cost and trading convenience."]}
]},
"npm-package-search":{title:"NPM Package Search",sections:[
{heading:"Package names and scopes",text:["Package names can be unscoped, such as lodash, or scoped, such as @org/package. Scopes help organizations group packages and can affect registry configuration and access control. Confirm the exact package identity because typosquatting packages may use names that look deceptively similar to popular dependencies."]},
{heading:"Downloads versus quality",text:["Weekly downloads can indicate adoption, but popularity is not the same as quality or safety. A specialized package may have modest downloads and still be well maintained, while a popular package can become abandoned. Combine download data with maintenance, issue activity, documentation and dependency health."]},
{heading:"Maintenance recency",text:["Check the publication date of recent versions, repository commits and maintainer responses. Long gaps are not automatically bad for stable software, but unresolved security or compatibility issues are a warning. A tiny mature utility may need few releases; a framework integration usually needs more active maintenance."]},
{heading:"Semantic versioning",text:["Semantic versioning uses major, minor and patch numbers to communicate compatibility intent, but maintainers do not always apply SemVer perfectly. Read changelogs before major upgrades and use lockfiles so production installs do not unexpectedly resolve to incompatible dependency versions."]},
{heading:"Dependencies and bundle size",text:["Every dependency can add transitive packages, install time, bundle weight and supply-chain exposure. Browser projects should inspect tree-shaking and bundle impact; server projects should inspect runtime and native-module requirements. Prefer a small dependency when it genuinely replaces substantial, well-tested work."]},
{heading:"TypeScript types",text:["TypeScript users should check whether a package ships declarations or relies on a separate @types package. Good types improve editor support and catch misuse, but stale declarations can be worse than no types. Verify that the published types match the package version and module format."]},
{heading:"License compatibility",text:["Licenses determine what you may do with a package and can matter in commercial distribution. MIT, Apache-2.0, GPL-family and custom licenses impose different obligations. Automated license scanners help, but ambiguous or missing licensing deserves manual review before adoption."]},
{heading:"Security advisories",text:["Inspect security advisories for the package and its dependency tree. A vulnerability’s practical risk depends on whether the affected code path is reachable in your application, but ignoring advisories entirely is unsafe. Keep lockfiles and dependency-update tooling part of the maintenance plan."]},
{heading:"ESM and CommonJS compatibility",text:["ESM and CommonJS packages behave differently across Node versions, bundlers and test runners. Check package exports, module type and documented import syntax before adoption. Compatibility problems often appear only in build or test environments, so validate the package in the project’s real toolchain."]},
{heading:"Evaluating alternatives before install",text:["Before installing, compare alternatives and ask whether the platform already provides the needed capability. Evaluate API clarity, maintenance burden, dependency count, performance and migration cost. Removing a dependency later can be expensive if its types or abstractions spread throughout the codebase."]}
]},
"european-mortgage-calculator":{title:"European Mortgage Calculator",sections:[
{heading:"Principal and deposit",text:["The financed principal is the property price minus the cash deposit plus any costs that are actually rolled into the loan. A larger deposit lowers loan-to-value and interest expense, but buyers must still preserve cash for taxes, legal fees, renovations and reserves."]},
{heading:"Nominal versus effective rates",text:["European lenders may quote nominal rates, effective annual rates or country-specific disclosure measures. Monthly-payment math must use a rate consistent with the compounding convention. Do not compare a nominal headline rate from one lender with an all-in effective rate from another."]},
{heading:"Amortization schedule",text:["A standard amortizing mortgage splits each payment between interest and principal. Early payments are interest-heavy because the outstanding balance is largest; later payments retire principal faster. The amortization schedule is essential for estimating the balance at a future sale or refinance date."]},
{heading:"Fixed versus variable periods",text:["Fixed-rate periods and variable-rate structures differ widely by country. A loan can be fixed for only an initial period even when the total term is decades. Model the payment after the fixed period using a plausible reset rate rather than assuming today’s rate lasts forever."]},
{heading:"Country-specific fees and taxes",text:["Purchase taxes, notary charges, registration, valuation and arrangement fees vary materially across European jurisdictions. Some are paid upfront and some may be financed. A monthly-payment comparison that ignores transaction costs can understate the cash required to complete the purchase."]},
{heading:"APR or equivalent disclosure metrics",text:["APR-like disclosure metrics attempt to combine interest and certain mandatory costs, but definitions vary. Use them to compare offers within the same regulatory framework, then inspect which fees are included. Optional insurance or future variable-rate changes may still sit outside the headline metric."]},
{heading:"Early repayment rules",text:["Early repayment can be free, capped or subject to compensation depending on the contract and jurisdiction. If you expect to sell, refinance or make large overpayments, include those rules in the comparison. A low rate can be less attractive if exit charges are substantial."]},
{heading:"Currency risk for cross-border borrowers",text:["Borrowing in a currency different from income creates exchange-rate risk. Even if the mortgage rate is lower, a weakening income currency can make payments and the outstanding balance more expensive in household-budget terms. Cross-border borrowers should stress-test exchange-rate moves."]},
{heading:"Affordability and stress rates",text:["Lenders often assess affordability using stressed interest rates rather than the introductory payment. Household debt, income stability and required living costs also matter. A calculator can estimate payment mechanics, but it cannot determine whether a lender will approve the application."]},
{heading:"Total cost versus monthly payment",text:["The lowest monthly payment is not necessarily the cheapest mortgage. Longer terms reduce required payments while increasing the years over which interest accrues. Compare total interest, fees, balance after the expected holding period and flexibility alongside the initial monthly amount."]}
]},
"lumpsum-vs-gold-calculator":{title:"Lumpsum vs Gold Calculator",sections:[
{heading:"Lump-sum compounding",text:["A lump-sum investment puts the full amount to work immediately, so the ending value depends on the compounded return from one purchase date. When gold is the comparison asset, avoid using an equity-style return assumption without considering gold’s different historical drivers and lack of operating earnings."]},
{heading:"Gold price return",text:["Gold return comes primarily from changes in market price and currency translation, not from internally generated cash flow. A calculator that compounds an assumed annual gold return is a scenario model; real prices can spend long periods flat or falling before recovering."]},
{heading:"Physical gold spreads and storage",text:["Physical gold involves dealer spreads, fabrication premiums, storage and insurance. These costs create a gap between quoted spot prices and the investor’s actual buy/sell economics. Small bars or jewellery can have especially high premiums that a simple spot-price projection misses."]},
{heading:"ETF or ETC fees",text:["Gold ETFs or ETCs can reduce storage friction but introduce management fees, tracking difference and product-structure considerations. Some vehicles hold physical metal while others use derivatives or different legal structures. Compare the actual instrument rather than treating every exchange-traded gold product as identical."]},
{heading:"No cash yield from gold",text:["Gold does not pay dividends, interest or rent. Its total return therefore relies heavily on price appreciation, unlike productive assets that can reinvest cash flows. This distinction matters when projecting long horizons because there is no underlying cash yield to compound unless the chosen vehicle adds one."]},
{heading:"Inflation and real return",text:["Gold is often discussed as an inflation hedge, but its relationship with inflation is uneven over shorter periods. Evaluate real return after inflation instead of assuming gold automatically preserves purchasing power every year. Entry valuation and currency moves can dominate for long stretches."]},
{heading:"Currency exposure",text:["For investors whose home currency is not the pricing currency of gold, exchange rates affect local returns. Gold can rise in dollars while producing a different result in rupees, pounds or euros. Use local-currency performance when comparing with a domestic investment goal."]},
{heading:"Tax treatment by jurisdiction",text:["Tax treatment differs for physical gold, exchange-traded products and jurisdictions. Capital-gains rates, holding periods and reporting rules can change after-tax outcomes. Keep tax assumptions separate from market-return assumptions so the calculator does not imply one universal treatment."]},
{heading:"Volatility and drawdowns",text:["Gold can experience substantial drawdowns even though it is often labeled defensive. Position size matters: a concentrated allocation can create large portfolio swings. Compare volatility and maximum-loss tolerance, not only the average return used in a future-value formula."]},
{heading:"Portfolio diversification role",text:["Gold’s strongest case is often diversification rather than winning a standalone return contest. Its correlation with stocks and bonds can change across regimes, but a modest allocation may behave differently during stress. Decide the portfolio role first, then judge whether the modeled allocation supports that role."]}
]},
"sip-vs-nps-calculator":{title:"SIP vs NPS Calculator",sections:[
{heading:"SIP as investment method versus NPS wrapper",text:["SIP is simply a recurring investment method; NPS is a regulated retirement account with its own contribution, asset-allocation, tax and withdrawal rules. An investor can make recurring contributions to NPS, so the meaningful comparison is usually an SIP into a chosen mutual fund versus recurring NPS contributions."]},
{heading:"NPS contribution and asset allocation",text:["NPS contributions are allocated among permitted asset classes such as equity, corporate debt and government securities according to the selected investment choice and regulatory limits. The expected return should reflect that mix rather than assuming NPS is one fixed-return product."]},
{heading:"Equity debt and government securities",text:["Equity can raise long-term growth potential and volatility, while government and corporate debt change interest-rate and credit exposure. Auto-choice allocations can adjust with age. Compare asset mixes on equivalent risk assumptions before attributing a return difference to the account wrapper."]},
{heading:"Tax deductions and regime rules",text:["NPS tax benefits depend on current Indian tax provisions, contribution type and tax regime. Deductions available to employees, self-employed investors and employer contributions are not identical. Use current-year rules rather than hard-coding an old deduction into a decades-long projection."]},
{heading:"Lock-in and retirement access",text:["NPS is designed for retirement and therefore has access restrictions that ordinary mutual funds do not. Partial withdrawals and exit conditions are governed by scheme rules. The liquidity cost matters if the same money might be needed for a home, education or emergency before retirement."]},
{heading:"Annuity requirement",text:["At exit, NPS rules can require part of the corpus to be used to purchase an annuity depending on the applicable withdrawal route. An annuity converts capital into income and has different return, liquidity and estate characteristics from keeping the full balance invested."]},
{heading:"Monthly SIP compounding",text:["A mutual-fund SIP is a series of purchases, so each instalment compounds for a different period. The projected corpus should be calculated from recurring cash flows. Comparing it with NPS should use the same contribution dates and total contributions where possible."]},
{heading:"Fees and fund choices",text:["NPS has relatively low account and fund-management costs, but the available fund menu and operational charges differ from a direct mutual-fund platform. Small annual cost gaps compound, yet asset allocation and tax treatment can have larger effects than fees alone."]},
{heading:"Liquidity differences",text:["Open-ended mutual funds generally offer greater redemption flexibility than NPS, subject to fund-specific exit loads and tax consequences. That flexibility has value even if it does not appear in the ending corpus. Retirement-only money can tolerate more lock-in than multipurpose savings."]},
{heading:"After-tax retirement income",text:["Compare after-tax retirement income, not only the displayed corpus. Account for tax benefits received while contributing, taxes on withdrawals under current rules, annuity income treatment, fees and the amount that remains liquid. A larger pre-tax balance can still produce a less flexible retirement outcome."]}
]},
"sp500-vs-bonds-calculator":{title:"S&P 500 vs Bonds Calculator",sections:[
{heading:"Equity total return",text:["S&P 500 return includes price change plus dividends; a price-only assumption understates long-run shareholder return. Equity earnings and valuations drive outcomes, so annual returns can vary dramatically around any average used in the calculator."]},
{heading:"Bond yield and coupon income",text:["Bond return comes from coupon income, changes in market price and reinvestment of cash flows. Yield to maturity can be a useful starting point for a high-quality bond held to maturity, but bond funds continually replace holdings and do not have one investor-specific maturity date."]},
{heading:"Duration and interest-rate risk",text:["Duration measures sensitivity to interest-rate changes. A bond or fund with duration of roughly seven years may lose about 7% from a one-percentage-point rate rise as a first-order estimate, though convexity and spread changes affect the actual result."]},
{heading:"Credit risk",text:["Government bonds and corporate bonds do not share the same credit risk. Corporate spreads can widen during recessions at the same time stocks fall, reducing diversification benefits. Match the bond assumption to the actual credit quality used in the portfolio."]},
{heading:"Dividends and reinvestment",text:["Dividend reinvestment is a major part of equity total return. If the calculator assumes dividends are reinvested, compare bonds on a total-return basis with coupons reinvested as well. Mixing price return on one side with total return on the other creates a biased result."]},
{heading:"Volatility and drawdowns",text:["Stocks typically experience larger short-term drawdowns than high-quality bonds, but bonds can also lose money when yields rise. Risk tolerance should be tested using plausible losses, not just annualized volatility or the ending value from a smooth compound-return formula."]},
{heading:"Inflation sensitivity",text:["Inflation erodes fixed nominal payments and can be particularly challenging for long-duration nominal bonds. Stocks have no guaranteed inflation hedge, but corporate revenues and earnings can adjust over time. Real-return assumptions help compare purchasing power rather than nominal balances."]},
{heading:"Rebalancing",text:["Rebalancing sells part of the outperforming asset and buys the underperforming one to restore target weights. This can control risk and systematically buy relatively cheaper assets, but it also creates transaction and tax considerations in taxable accounts."]},
{heading:"Time horizon",text:["Time horizon changes the acceptable mix. Money needed within a few years may not recover from a major equity decline, while very long horizons can better tolerate volatility. Bond maturity and duration should also be aligned with the timing of liabilities."]},
{heading:"Portfolio role rather than winner selection",text:["The decision is rarely S&P 500 or bonds as an all-or-nothing choice. Bonds can provide liquidity and volatility control while equities provide growth potential. Use the calculator to understand tradeoffs across allocations such as 80/20, 60/40 or 40/60 rather than searching for a permanent winner."]}
]},
"stocks-shares-isa-vs-cash-isa-calculator":{title:"Stocks & Shares ISA vs Cash ISA Calculator",sections:[
{heading:"ISA tax wrapper",text:["Both products sit inside the UK ISA tax wrapper, but the assets are different. A Cash ISA holds cash-like savings, while a Stocks and Shares ISA can hold funds, shares and other investments. The tax shelter does not make their investment risks equivalent."]},
{heading:"Cash interest certainty",text:["Cash ISA interest is generally predictable until the provider changes a variable rate or a fixed term ends. Stocks and Shares ISA values fluctuate with markets and can fall below contributions. Compare expected return with the possibility of loss, not just headline rates."]},
{heading:"Investment market risk",text:["Time horizon is central. Cash is suitable for near-term spending and emergency reserves because nominal value is stable, while diversified investments are usually considered for longer horizons that can absorb market declines. A five-year rule of thumb is not a guarantee of recovery."]},
{heading:"Time horizon",text:["Investment platforms and funds can charge account, dealing and fund fees. Cash ISAs can also have opportunity costs through lower rates or access restrictions. Model the charges actually applicable to the selected providers rather than assuming both wrappers are free."]},
{heading:"Fees",text:["Inflation can reduce the real value of cash even when the nominal balance rises. Investments have greater short-term risk but may offer stronger long-run inflation-beating potential. Compare future purchasing power after inflation when the goal is many years away."]},
{heading:"Inflation",text:["FSCS protection for eligible cash deposits and protections applying to investment firms are not the same as protection from market losses. An investment can legitimately decline in value without any provider failure. Do not interpret regulatory protection as a guarantee of investment performance."]},
{heading:"FSCS and investment protection distinctions",text:["Easy-access, notice and fixed-term Cash ISAs have different withdrawal rules, and some ISAs are flexible while others are not. Stocks and Shares ISA withdrawals can require selling assets and waiting for settlement. Liquidity needs should influence the product choice."]},
{heading:"Withdrawal flexibility",text:["The annual ISA allowance applies across qualifying ISA subscriptions under current rules. Moving money between providers should normally use the formal ISA transfer process when preserving wrapper status matters, rather than withdrawing and recontributing without checking allowance consequences."]},
{heading:"ISA allowance",text:["Asset allocation inside a Stocks and Shares ISA determines most of its risk. A short-duration bond fund, global equity index and single speculative stock are all possible holdings but behave very differently. The wrapper alone cannot supply a sensible return assumption."]},
{heading:"Asset allocation",text:["A practical plan can use both: cash for near-term needs and investments for long-term goals. The calculator should show the consequence of different return assumptions and horizons, while the investor decides how much volatility and liquidity risk is acceptable."]}
]},
"term-vs-ulip-calculator":{title:"Term Insurance vs ULIP Calculator",sections:[
{heading:"Pure insurance versus insurance-investment bundle",text:["Term insurance is primarily protection: the premium buys a death benefit for a defined term without building a large investment corpus. A ULIP combines life cover with market-linked investment. Comparing them requires separating the cost of insurance from the investment component."]},
{heading:"Sum assured",text:["Sum assured should be judged against income replacement, debts, dependants and major goals rather than chosen only because a premium looks affordable. A ULIP with a modest sum assured can leave an underinsurance gap even if its projected fund value appears attractive."]},
{heading:"Premium allocation",text:["ULIP premiums can be subject to allocation-related charges depending on product terms, reducing the amount that reaches investment funds. Modern products vary widely, so use the actual policy illustration instead of assuming one standard charge schedule."]},
{heading:"Mortality charges",text:["Mortality charges pay for the life-risk cover within a ULIP and can depend on age, sum at risk and policy design. These charges may change as the fund value changes. A simple compound-return projection that invests the entire premium can therefore overstate the fund value."]},
{heading:"Fund management charges",text:["Fund-management charges reduce the return credited to ULIP investment funds. Compare net returns after all recurring charges with the expense ratio and platform costs of the alternative investment used alongside term insurance."]},
{heading:"Lock-in and surrender rules",text:["ULIPs have lock-in and surrender rules that affect access to money. Exiting early can have consequences different from redeeming an open-ended mutual fund. Liquidity should be valued explicitly if financial circumstances may change before the intended policy horizon."]},
{heading:"Investment return assumptions",text:["Projected investment returns in policy illustrations are scenarios, not guarantees for market-linked funds. Equity-oriented ULIP funds can fall sharply, while debt-oriented funds have interest-rate and credit risk. Match the assumed return to the selected fund allocation."]},
{heading:"Tax treatment",text:["Tax treatment of premiums, maturity proceeds and death benefits depends on current Indian tax law and policy characteristics. Rules have changed over time, including treatment of certain high-premium policies. Verify the policy issue date and current provisions rather than relying on old blanket statements."]},
{heading:"Separating protection and investing",text:["Buying term insurance and investing separately can make insurance cost and investment performance easier to evaluate. A ULIP may appeal to someone who values a bundled structure and accepts its rules. The fair comparison uses the same required life cover and the same out-of-pocket budget."]},
{heading:"Policy illustration limitations",text:["Policy illustrations contain assumptions about returns, charges and benefits. Read the benefit illustration and policy wording together, paying attention to guaranteed versus non-guaranteed values. A calculator can compare modeled cash flows but cannot replace product-specific disclosures."]}
]},
"sip-vs-stocks-calculator":{title:"SIP vs Stocks Calculator",sections:[
{heading:"SIP is a schedule not an asset class",text:["SIP is a contribution schedule, not an asset class. An SIP commonly invests into a mutual fund, while “stocks” usually means direct ownership of individual companies. The real comparison is diversified fund investing on a schedule versus selecting and managing individual shares."]},
{heading:"Diversified fund versus individual-stock risk",text:["A diversified fund can spread company-specific risk across dozens or hundreds of holdings. A portfolio of a few individual stocks can suffer permanent loss if one business fails. Direct-stock investors need a deliberate diversification policy rather than assuming several familiar names are enough."]},
{heading:"Monthly cash flows",text:["Monthly contributions create multiple purchase prices and holding periods. The SIP projection should calculate each instalment separately. A direct-stock investor can also invest monthly, so contribution timing should be held constant when comparing investment-selection approaches."]},
{heading:"Rupee-cost averaging",text:["Rupee-cost averaging buys more units or shares when prices are lower for a fixed contribution. It reduces timing dependence but does not guarantee a profit. A prolonged market decline can leave both an SIP fund and a stock portfolio below cost."]},
{heading:"Research burden",text:["Direct stock investing requires analysis of business quality, valuation, financial statements, industry risk and portfolio construction. The time and skill required are real costs even if no advisory fee is charged. A broad index fund outsources much of security selection."]},
{heading:"Fees and brokerage",text:["Brokerage, exchange charges, taxes and bid-ask spreads can affect frequent stock purchases. Mutual funds have expense ratios and may have exit loads. Compare the full cost stack at the actual investment size because fixed charges are proportionally larger on small trades."]},
{heading:"Dividends",text:["Dividends are part of total stock return and should be included when comparing with a fund’s growth. Reinvested dividends compound; cash dividends that are spent do not. Avoid comparing a fund total-return assumption with stock price appreciation alone."]},
{heading:"Taxes",text:["Tax can differ based on holding period, realized gains and distributions. Frequent stock trading may realize gains more often than a buy-and-hold fund strategy. Each SIP instalment or stock purchase also creates its own tax lot and holding period."]},
{heading:"Concentration risk",text:["Concentration risk is the defining danger of a small direct-stock portfolio. One accounting problem, regulatory event or technological disruption can dominate returns. Position-size limits and sector diversification matter more than the smooth average return entered into a calculator."]},
{heading:"Benchmarking outcomes",text:["Benchmark direct-stock performance against an investable diversified alternative after costs and taxes. Beating a benchmark in one year can be luck; sustained outperformance should be evaluated over a full market cycle and with comparable risk. The calculator is most useful for setting that hurdle rate."]}
]},
"uk-income-tax-calculator":{title:"UK Income Tax Calculator",sections:[
{heading:"Taxable income",text:["Taxable income starts from relevant income sources and then applies allowable reliefs and the Personal Allowance where available. Gross salary is not always identical to taxable pay because pension arrangements, benefits and deductions can alter the amount subject to income tax."]},
{heading:"Personal allowance",text:["The Personal Allowance is set for each tax year and can be reduced when adjusted net income exceeds the applicable threshold. That taper creates a band in which the effective marginal tax rate can be much higher than the headline higher-rate percentage."]},
{heading:"Basic higher and additional bands",text:["England, Wales and Northern Ireland use basic, higher and additional income-tax bands under the applicable tax-year rules. Only the slice of income inside each band is taxed at that band’s rate; moving into a higher band does not cause all income to be taxed at the higher percentage."]},
{heading:"Allowance taper",text:["High-income taxpayers can lose Personal Allowance through the taper, so two people with the same gross pay can have different effective rates if pension contributions or other adjustments change adjusted net income. Model the taper explicitly rather than applying one flat tax rate."]},
{heading:"Scottish income tax differences",text:["Scottish taxpayers have separate earned-income bands and rates. A calculator using England/Wales/Northern Ireland bands can therefore be materially wrong for Scottish employment or pension income. Residency for Scottish tax purposes follows tax rules, not simply employer location."]},
{heading:"National Insurance separation",text:["National Insurance is separate from income tax and uses its own thresholds and rules. A result labeled “income tax” should not be interpreted as total payroll deductions unless NI is calculated separately and added. Student loans and workplace pensions can also affect take-home pay."]},
{heading:"Pension contributions",text:["Pension contributions can receive tax relief in different ways depending on the scheme, such as relief at source or net pay. Contributions can also affect adjusted net income and therefore allowance tapering or other thresholds. Use the scheme’s actual mechanism when estimating take-home pay."]},
{heading:"Benefits and other income",text:["Benefits in kind, savings interest, dividends, rental income and other sources can change the final tax position. Some use separate allowances or rates. A salary-only calculator is therefore a payroll estimate, not a complete Self Assessment calculation for someone with multiple income sources."]},
{heading:"Marginal versus effective rate",text:["Marginal rate is the tax on the next pound of relevant income; effective rate is total tax divided by total income. They answer different questions. Marginal rate is useful for evaluating bonuses or pension contributions, while effective rate describes the overall burden."]},
{heading:"Tax-year thresholds",text:["UK thresholds can change by tax year, and frozen thresholds can increase tax even without a rate rise as nominal wages grow. Always label the tax year used by the calculator and verify current HMRC figures before relying on the output for payroll or planning."]}
]},
"htaccess-generator":{title:".htaccess Generator",sections:[
{heading:"Apache directory configuration",text:[".htaccess is an Apache per-directory configuration file. It is read only when the server and virtual-host configuration permit overrides, so a perfectly written file can appear ineffective if AllowOverride is disabled. Nginx and many managed platforms do not use .htaccess at all."]},
{heading:"Mod_rewrite rules",text:["mod_rewrite provides rule-based URL rewriting. RewriteRule matches a URL-path pattern and can substitute a new path or URL, while flags control behavior such as case sensitivity, query strings and whether processing should stop. Pattern scope differs between server config and .htaccess context."]},
{heading:"RewriteCond and RewriteRule",text:["RewriteCond adds conditions that must be satisfied before the following RewriteRule runs. Conditions can inspect host names, HTTPS state, files, directories, headers or environment variables. Complex chains should be kept readable because one misplaced condition can create unexpected routing."]},
{heading:"Redirect status codes",text:["Permanent redirects normally use 301 or 308, while temporary redirects use 302 or 307 depending on method-preservation needs. Redirect status affects browser caching and search-engine interpretation, so do not mark a migration permanent until the destination is stable."]},
{heading:"Canonical HTTPS and host redirects",text:["HTTPS and canonical-host redirects should produce one hop where possible. A common mistake redirects HTTP to HTTPS and then separately redirects www to non-www, creating chains. Combine conditions carefully and exclude the canonical request to avoid infinite loops."]},
{heading:"Access control",text:["Apache access control can restrict files or directories, but syntax differs between older and newer Apache versions. Security-sensitive rules should be enforced at the strongest available configuration layer. Do not rely on generated snippets without confirming server version and override permissions."]},
{heading:"Headers and caching",text:["Headers can control caching, security policies and content behavior when the relevant Apache modules are enabled. Cache-Control rules should distinguish versioned static assets from HTML. Security headers such as CSP require application-specific testing rather than one universal copied value."]},
{heading:"ErrorDocument",text:["ErrorDocument can map status codes to custom local pages or external URLs. The custom handler must itself be reachable and should return the intended status. A broken error route can hide the original problem or create recursive errors."]},
{heading:"AllowOverride requirement",text:["AllowOverride determines which classes of directives Apache permits in .htaccess. Shared hosting often exposes only a subset. If a generated directive triggers a 500 error, inspect the Apache error log and verify that both the module and override category are enabled."]},
{heading:"Testing to avoid redirect loops",text:["Test rewrite changes with curl and browser developer tools before deploying broadly. Check representative paths, query strings, trailing slashes, files that should bypass rewriting and both canonical/noncanonical hosts. Keep a rollback copy because a syntax error in .htaccess can make the entire directory return server errors."]}
]},
"nsc-vs-fd-calculator":{title:"NSC vs FD Calculator",sections:[
{heading:"NSC tenure and compounding",text:["National Savings Certificate has a government-declared tenure and interest structure, while bank fixed deposits offer many selectable tenures and rates. Compare instruments over the same horizon; otherwise a higher maturity value may simply reflect money being locked for longer."]},
{heading:"FD tenure and rate choices",text:["NSC interest is compounded according to the scheme’s rules and paid at maturity rather than as periodic cash income. FD compounding depends on whether the deposit is cumulative and on the bank’s compounding convention. Use effective maturity values instead of comparing only quoted annual rates."]},
{heading:"Section 80C context",text:["Eligible NSC investment can fall within Section 80C subject to current law and the taxpayer’s available limit. Many ordinary bank FDs do not qualify unless they are specific tax-saving deposits. A tax deduction has value only if the investor can actually use it."]},
{heading:"Interest taxation",text:["FD interest is generally taxable according to the investor’s tax situation, and TDS mechanics are not the same as final tax liability. NSC interest also has tax treatment that must be understood year by year. Compare after-tax return rather than assuming either product is tax-free."]},
{heading:"Reinvested NSC interest treatment",text:["Interest accrued on NSC in earlier years can have reinvestment-related Section 80C treatment under applicable rules, while final-year interest is handled differently because it is not reinvested for another year. This nuance is easy to miss in a simple maturity calculator."]},
{heading:"Liquidity and premature exit",text:["NSC has restricted premature encashment except in specified circumstances. Bank FDs are often breakable but can apply a lower effective rate or penalty. Emergency-fund money should not be committed solely because the headline rate is attractive."]},
{heading:"Bank credit risk and deposit insurance",text:["NSC carries sovereign backing, while bank deposits carry bank credit exposure subject to deposit-insurance limits and conditions. Large FD balances may exceed insured amounts. Risk comparison should therefore consider issuer and diversification, not only return."]},
{heading:"Rate-lock and reinvestment risk",text:["An FD can lock a rate only for its chosen tenure; when it matures, reinvestment may occur at a different rate. NSC also has rate-setting rules for new purchases. For goals spanning multiple deposit cycles, reinvestment-rate assumptions can materially affect the final result."]},
{heading:"Inflation-adjusted return",text:["Inflation reduces the purchasing power of both fixed-income outcomes. A 7% nominal return with 5% inflation produces only a modest real gain before tax. Investors in higher tax brackets can experience an even lower or negative real after-tax return."]},
{heading:"After-tax maturity comparison",text:["For a fair comparison, calculate maturity value, taxes, usable deductions, liquidity constraints and risk over the same dates. If the FD tenure is shorter, include a realistic reinvestment assumption. The best choice depends on the investor’s tax position and need for access, not just the displayed maturity amount."]}
]},
"401k-vs-taxable-account-calculator":{title:"401(k) vs Taxable Account Calculator",sections:[
{heading:"Pre-tax or Roth 401k treatment",text:["A Traditional 401(k) can defer current income tax on eligible contributions, while Roth 401(k) contributions are after tax. A taxable brokerage receives after-tax money. The comparison must specify which 401(k) tax treatment is being modeled because the cash-flow economics are different."]},
{heading:"Employer match",text:["Employer match can dominate the decision. If an employer contributes 50 cents per dollar up to a stated percentage of pay, failing to contribute enough can forfeit compensation. Model vesting rules as well, because an unvested match may be lost after an early job departure."]},
{heading:"Contribution limits",text:["401(k) contribution limits are tax-year specific and generally much higher than IRA limits, with additional rules for catch-up contributions. A calculator should cap or flag unrealistic contributions rather than assuming any entered amount can receive 401(k) treatment."]},
{heading:"Taxable-account flexibility",text:["A taxable account has no retirement-plan contribution limit and generally allows withdrawals at any time without a retirement-plan early-distribution penalty. That flexibility can be valuable for early retirement, a home purchase or other pre-retirement goals even when the tax drag is higher."]},
{heading:"Dividend and capital-gains tax drag",text:["Dividends, interest and realized capital gains can create annual tax drag in a taxable portfolio. Tax-efficient index funds may defer much of the gain until sale, while high-turnover funds or taxable bonds can create larger annual liabilities. Use an after-tax return assumption appropriate to the holdings."]},
{heading:"Withdrawal rules",text:["401(k) withdrawals follow plan and tax rules, and early access can trigger tax and penalties unless an exception or planning strategy applies. Loans, Rule of 55 access and rollovers have separate conditions. Do not treat the entire retirement balance as freely spendable at any age."]},
{heading:"RMDs",text:["Required minimum distribution rules can force taxable withdrawals from pre-tax retirement money later in life under current law. Taxable brokerage accounts do not have RMDs. This can affect retirement tax brackets and estate planning even if both accounts reach the same pre-tax value."]},
{heading:"Fees and fund menus",text:["401(k) plans can have administrative fees and limited fund menus, while taxable brokerages often offer broader investment choice. A low-cost institutional 401(k) can be excellent; an expensive plan can narrow the tax advantage. Compare actual all-in investment and plan costs."]},
{heading:"Equal take-home-cost comparison",text:["Equal account contributions are not an equal take-home-cost comparison when one contribution is pre-tax. If a Traditional 401(k) saves current tax, model what happens to that tax saving. Investing it in the taxable account produces a more economically balanced comparison than assuming it disappears."]},
{heading:"Early retirement access planning",text:["Early retirees often combine account types. Taxable assets can fund years before penalty-free retirement access, while 401(k) assets continue tax-deferred growth and may later be rolled to an IRA. The useful question is usually how much to place in each bucket, not whether one account should replace the other entirely."]}
]},
}
export default function CalculatorBatch57DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <section className="mt-10 space-y-6"><h2 className="text-2xl font-bold">{g.title} In-Depth Guide</h2>{g.sections.map((s,i)=><div key={i}><h3 className="text-xl font-semibold mb-2">{s.heading}</h3>{s.text.map((t,j)=><p key={j} className="mb-3 leading-7">{t}</p>)}</div>)}</section>}